    val tq = "\"\"\""
    val suffix: String =
      if (testNameSuffix.nonEmpty) testNameSuffix.get
      else ""

    observationKind match {
      case scp_candidate.runtimemonitor.ObservationKind.HVACSupervisor_Instance_supervision_requestQualifier_postInit =>
        return (st"""// Begin test cases for HVACSupervisor_Instance_supervision_requestQualifier_postInit
                    |
                    |test(s"HVACSupervisor_Instance_supervision_requestQualifier_postInit: Check Post-condition$suffix") {
                    |  val postJson: String = st${tq}${postContainer.get}${tq}.render
                    |  val postContainer = scp_candidate.JSON.toHVAC_Visibility_Priority_SupervisorRequestQualifier_supervision_requestQualifier_PostState_Container_PS(postJson).left
                    |  assert(scp_candidate.HVAC_Visibility_Priority_Supervisor.RequestQualifier_supervision_requestQualifier_GumboX.inititialize_IEP_Post_Container(postContainer))
                    |}
                    |// End test cases for HVACSupervisor_Instance_supervision_requestQualifier_postInit""")
      case scp_candidate.runtimemonitor.ObservationKind.HVACSupervisor_Instance_supervision_requestQualifier_postCompute =>
        return (st"""// Begin test cases for HVACSupervisor_Instance_supervision_requestQualifier_postCompute
                    |
                    |test(s"HVACSupervisor_Instance_supervision_requestQualifier_postCompute: Check Post-condition$suffix") {
                    |  val preJson: String = st${tq}${preContainer.get}${tq}.render
                    |  val postJson: String = st${tq}${postContainer.get}${tq}.render
                    |  val preContainer = scp_candidate.JSON.toHVAC_Visibility_Priority_SupervisorRequestQualifier_supervision_requestQualifier_PreState_Container_PS(preJson).left
                    |  val postContainer = scp_candidate.JSON.toHVAC_Visibility_Priority_SupervisorRequestQualifier_supervision_requestQualifier_PostState_Container_PS(postJson).left
                    |  if (verbose) {
